"""The SDK a peg targets: the ``sdk`` key in its ``workpeg.json``.

Workpeg is to build a released peg itself, with its own builder, at the SDK
version the peg names (owner, 2026-11-02: "a live peg is built by Workpeg's
own compiler, at the peg's target SDK version"). That builder does not exist
yet: today a peg's page is still compiled outside Workpeg, and the target
says which SDK that build should use. The version is written in the
project's root ``workpeg.json``::

    {"namespace": "my-peg", "sdk": "0.160.0", ...}

It is one exact ``X.Y.Z``, never a range: the reviewer approves one build, and
a range would let the build under review differ from the build that runs.
``workpeg project create`` writes it at the SDK the developer has installed,
the way it stamps the function's ``pegfn-base``, and ``workpeg project target
X.Y.Z`` moves it.

The floor is 0.150.0, the first release whose builds carry ``SCRIPT_POLICY``
(owner, 2026-11-12, decision 6). A peg built by an older SDK would ship no
script policy, so Workpeg will not build one.

A target that differs from the installed SDK is a warning here, never a
refusal: the local build is the developer's own and is thrown away, and the
build that will count is Workpeg's, at the target.
"""
from __future__ import annotations

import json
import os
import tempfile
from pathlib import Path

from workpeg import function_base

__all__ = [
    "FLOOR", "KEY", "PLACEHOLDER", "TargetError", "check", "fill",
    "installed", "read", "require", "set_target", "warning",
]

#: The key in ``workpeg.json``.
KEY = "sdk"

#: The lowest target Workpeg will build: the first release with
#: SCRIPT_POLICY.
FLOOR = "0.150.0"

#: Substituted into the project template's ``workpeg.json``.
PLACEHOLDER = "REPLACE_SDK_VERSION"

#: The manifest's name, at the project root.
MANIFEST = "workpeg.json"


class TargetError(Exception):
    """The target cannot be read or is not one Workpeg will build. The
    message is for the developer, and names the command that fixes it."""


def _parts(version: str) -> tuple:
    return tuple(int(part) for part in version.split("."))


def installed() -> str:
    """The SDK on this computer, as ``workpeg --version`` says it."""
    from workpeg import __version__
    return __version__


def suggested() -> str:
    """The target a new peg gets: this SDK, or in a dev tree (version
    ``0``) the newest release its changelog records."""
    return function_base.base_version()


def check(value: object) -> str:
    """*value* as a target, or :class:`TargetError` saying why not."""
    if not isinstance(value, str) or not function_base.RELEASE.fullmatch(
            value):
        shown = json.dumps(value) if isinstance(
            value, (str, int, float, bool, type(None))) else type(
            value).__name__
        raise TargetError(
            f'"{KEY}" in {MANIFEST} is {shown}, not an exact SDK version '
            f"such as {FLOOR}. Workpeg will build a peg with one exact "
            f"release, never a range. Set it with `workpeg project target "
            f"X.Y.Z`.")
    if _parts(value) < _parts(FLOOR):
        raise TargetError(
            f"SDK {value} is below {FLOOR}, the first release whose builds "
            f"carry the script policy, and Workpeg will not build a peg "
            f"below it. {_move_hint()}")
    return value


def _move_hint() -> str:
    """How to move a target: to this SDK, unless this SDK is itself below
    the floor (a stale install, or a dev tree whose installed metadata is
    stale), which no target may be."""
    try:
        here = suggested()
    except function_base.BaseVersionError:
        here = None
    if here is not None and _parts(here) >= _parts(FLOOR):
        return f"Move the target with `workpeg project target {here}`."
    return (f"This SDK says it is {here or 'no release'}, below {FLOOR} "
            f"too: install a current one (`pip install --upgrade workpeg`, "
            f"or `pip install -e .` in an SDK checkout whose installed "
            f"version is stale), then move the target with `workpeg "
            f"project target X.Y.Z`, its version.")


def _manifest(project: "str | Path") -> Path:
    return Path(project) / MANIFEST


def _load(path: Path) -> dict:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        raise TargetError(
            f"There is no {MANIFEST} in {path.parent}. Run this from the "
            f"peg's own folder, the one `workpeg project create` made, or "
            f"pass --path.") from None
    except (OSError, UnicodeDecodeError, ValueError) as exc:
        raise TargetError(f"{path} cannot be read as JSON: {exc}") from None
    if not isinstance(data, dict):
        raise TargetError(f"{path} is not a JSON object.")
    return data


def read(project: "str | Path") -> "str | None":
    """The raw ``sdk`` value of *project*'s ``workpeg.json``, or None when
    it has no such key. Not checked: :func:`require` checks it."""
    data = _load(_manifest(project))
    return data.get(KEY)


def read_manifest(path: "str | Path") -> "object":
    """The raw ``sdk`` value of the ``workpeg.json`` at *path*, or None."""
    return _load(Path(path)).get(KEY)


def require(project: "str | Path") -> str:
    """The checked target of *project*, refused when missing: what
    ``workpeg project submit`` asks before it packs anything."""
    data = _load(_manifest(project))
    if KEY not in data:
        raise TargetError(
            f'{MANIFEST} names no target SDK. Workpeg will build a peg with '
            f'the SDK its "{KEY}" key names, and `workpeg project submit` '
            f"refuses one without it. Set it with `workpeg project target "
            f"{suggested()}`.")
    return check(data[KEY])


def warning(target: object, version: "str | None" = None) -> "str | None":
    """The one line to print when *target* is not the SDK installed here,
    or None when they agree. Never a refusal (see the module docstring)."""
    if target is None:
        return (
            f'{MANIFEST} names no target SDK. Workpeg will build a peg with '
            f'the SDK its "{KEY}" key names, and `workpeg project submit` '
            f"refuses one without it. Set it with `workpeg project target "
            f"{suggested()}`.")
    try:
        target = check(target)
    except TargetError as exc:
        return str(exc)
    here = installed() if version is None else version
    if here == target:
        return None
    if not function_base.RELEASE.fullmatch(here):
        return (
            f"This peg targets SDK {target}, and this computer runs an "
            f"unreleased SDK (version {here}). Workpeg will build the peg "
            f"with {target}, so what you see here may differ from what "
            f"ships.")
    return (
        f"This peg targets SDK {target}, and this computer has SDK {here}. "
        f"Workpeg will build the peg with {target}, so what you see here "
        f"may differ from what ships. Install it with `pip install "
        f"workpeg=={target}`, or move the target with `workpeg project "
        f"target {here}`.")


def set_target(project: "str | Path", version: str) -> "tuple[object, str]":
    """Write *version* as *project*'s target. Returns ``(old, new)``, where
    *old* is the raw value it replaced, or None.

    The rest of the file is kept, key for key and in order; a new ``sdk``
    goes right after ``namespace``. The file is replaced in one rename, so
    an interrupted write never leaves half a manifest.
    """
    version = check(version)
    path = _manifest(project)
    data = _load(path)
    old = data.get(KEY)
    if KEY in data:
        data[KEY] = version
    else:
        rebuilt: dict = {}
        for key, value in data.items():
            rebuilt[key] = value
            if key == "namespace":
                rebuilt[KEY] = version
        if KEY not in rebuilt:
            rebuilt = {KEY: version, **data}
        data = rebuilt
    text = json.dumps(data, indent=2, ensure_ascii=False) + "\n"
    fd, temp = tempfile.mkstemp(dir=path.parent, prefix=".workpeg.json.")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(text)
        try:
            os.chmod(temp, path.stat().st_mode & 0o777)
        except OSError:
            pass
        os.replace(temp, path)
    except BaseException:
        try:
            os.unlink(temp)
        except OSError:
            pass
        raise
    return old, version


def fill(text: str, version: "str | None" = None) -> str:
    """*text* with the template's target placeholder filled in."""
    if PLACEHOLDER not in text:
        return text
    return text.replace(PLACEHOLDER, version or suggested())
